"""RoboPaint 口: camera-calibrated brush strokes; no resets or privileged state."""
import sys, json, time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot
r=Robot()
OUT=Path('/app/output')
spec=r.spec()
Q=np.array([-3.98743083e-7,1.,-3.55532393e-7,-2.86572686e-8])
Z=.0202
seq=len(list(OUT.glob('run_*')))
last=np.array(r.get_obs(cameras=[]).meta['proprio']['now'][7:10])
def go(points, note='', cameras=['practice_cam'], fps=10):
    global last,seq
    # points = x,y,z,duration; interpolate at the control frequency
    poses=[]
    for x,y,z,duration in points:
        dest=np.array([x,y,z]); n=max(1,round(duration/.05))
        poses.extend(np.c_[np.linspace(last,dest,n+1)[1:],np.tile(Q,(n,1))])
        last=dest
    for i in range(0,len(poses),180):
        seq+=1
        a=np.asarray(poses[i:i+180]); np.save(OUT/f'actions_{seq:03d}.npy',a)
        res=r.submit('ee_pose',a,dt=.05,cameras=cameras,video='frames',video_fps=fps,note=note)
        res.save(str(OUT/f'run_{seq:03d}'))
        for cam,img in res.last.items(): Image.fromarray(img).save(OUT/f'{cam}.png')
        print('run',seq,'tip',np.round(res.group('tcp_pose',now=True)[:3],6),'plan',res.meta.get('plan'),'stop',res.stopped,flush=True)
        if res.stopped: raise RuntimeError('Stopped; inspect before continuing')
    return res

def dip():
    go([(*last[:2],.08,.7),(-.1,.154,.08,2.5),(-.1,.154,.025,1.0),(-.1,.154,.025,.4),(-.1,.154,.08,.8)],'dip',cameras=['scene_cam'])
def park():
    return go([(*last[:2],.08,.7),(-.04,.19,.1,2.5)],'park',cameras=['canvas_cam','practice_cam','scene_cam'])
def practice(u,v,depth):
    # practice image coordinate in millimetres; X to right, Y toward base
    return (.0135925-v/1000,-.1359035-u/1000,Z-depth/1000)
def main(u,v,depth):
    return (.0135925-(v+.5)*.00022186,.1135925-(u+.5)*.00022186,Z-depth/1000)
if __name__=='__main__' and '--replay' in sys.argv:
    for phase in sorted(OUT.glob('phase*.py')): exec(phase.read_text())
